import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { AIDisclaimerProps } from "./ai-disclaimer.types";
import { AIDisclaimerClasses, StyledAIDisclaimer } from "./ai-disclaimer.styles";

export const AIDisclaimer = forwardRef<HTMLDivElement, AIDisclaimerProps>(
  ({ className, children, variant = "default", ...props }, ref) => {
    const theme = useTheme();

    return (
      <StyledAIDisclaimer
        ref={ref}
        className={clsx(AIDisclaimerClasses.root, className)}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledAIDisclaimer>
    );
  },
);

AIDisclaimer.displayName = "AI.Disclaimer";
